import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 조회 항목 값은 명세에 목록이 없어 AC 문구(품의서·원인행위·결의서 현황, 예산 대비)에서 정한 값이다.
const STATUS_ITEMS = ['품의서', '원인행위', '결의서', '예산'];
const COMPARISON_FORMS = ['기본', '상세'];
const APPROVAL_STATUSES = ['기안', '결재대기', '진행중', '승인', '보류', '반려', '회수', '완료'];
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

function text(v: unknown): string {
  return typeof v === 'string' ? v.trim() : '';
}

function wholeNumber(v: unknown, name: string, fallback: number): number {
  const s = text(v);
  if (s === '') {
    return fallback;
  }
  if (!/^\d+$/.test(s)) {
    throw new ApiError(400, 'VALIDATION_FAILED', name + ' 값이 올바르지 않습니다.');
  }
  return Number(s);
}

function idText(v: unknown, name: string): string {
  const s = text(v);
  if (s !== '' && !/^\d+$/.test(s)) {
    throw new ApiError(400, 'VALIDATION_FAILED', name + ' 값이 올바르지 않습니다.');
  }
  return s;
}

interface Filter {
  projectId: string;
  budgetItemId: string;
  approvalStatus: string;
}

function extraWhere(f: Filter, projectCol: string, itemCol: string, statusCol: string): string {
  let sql = '';
  if (f.projectId !== '') {
    sql += ' AND ' + projectCol + ' = CAST(:projectId AS bigint)';
  }
  if (f.budgetItemId !== '') {
    sql += ' AND ' + itemCol + ' = CAST(:budgetItemId AS bigint)';
  }
  if (f.approvalStatus !== '') {
    sql += ' AND ' + statusCol + ' = :approvalStatus';
  }
  return sql;
}

function baseSql(statusItem: string, form: string, f: Filter): string {
  if (statusItem === '품의서') {
    return 'SELECT p.project_id AS "projectId", p.project_name AS "projectName", '
      + 'b.budget_item_id AS "budgetItemId", b.item_name AS "budgetItemName", '
      + 'r.approval_status AS "approvalStatus", COUNT(*) AS "count", SUM(r.amount) AS "amount", '
      + 'ROUND(SUM(r.amount) * 100 / NULLIF(SUM(SUM(r.amount)) OVER (PARTITION BY p.project_id), 0), 2) AS "ratio" '
      + 'FROM purchase_request r '
      + 'JOIN project p ON p.project_id = r.project_id '
      + 'JOIN budget_item b ON b.budget_item_id = r.budget_item_id '
      + 'WHERE CAST(r.created_at AS date) BETWEEN CAST(:dateFrom AS date) AND CAST(:dateTo AS date)'
      + extraWhere(f, 'r.project_id', 'r.budget_item_id', 'r.approval_status')
      + ' GROUP BY p.project_id, p.project_name, b.budget_item_id, b.item_name, r.approval_status';
  }
  if (statusItem === '원인행위') {
    return 'SELECT p.project_id AS "projectId", p.project_name AS "projectName", '
      + 'b.budget_item_id AS "budgetItemId", b.item_name AS "budgetItemName", '
      + 'r.approval_status AS "approvalStatus", COUNT(*) AS "count", SUM(c.amount) AS "amount", '
      + 'ROUND(SUM(c.amount) * 100 / NULLIF(SUM(SUM(c.amount)) OVER (PARTITION BY p.project_id), 0), 2) AS "ratio" '
      + 'FROM commitment c '
      + 'JOIN budget_item b ON b.budget_item_id = c.budget_item_id '
      + 'LEFT JOIN purchase_request r ON r.purchase_request_id = c.purchase_request_id '
      + 'LEFT JOIN project p ON p.project_id = r.project_id '
      + 'WHERE CAST(c.created_at AS date) BETWEEN CAST(:dateFrom AS date) AND CAST(:dateTo AS date)'
      + extraWhere(f, 'r.project_id', 'c.budget_item_id', 'r.approval_status')
      + ' GROUP BY p.project_id, p.project_name, b.budget_item_id, b.item_name, r.approval_status';
  }
  if (statusItem === '결의서') {
    return 'SELECT p.project_id AS "projectId", p.project_name AS "projectName", '
      + 'b.budget_item_id AS "budgetItemId", b.item_name AS "budgetItemName", '
      + 'e.approval_status AS "approvalStatus", COUNT(*) AS "count", SUM(e.amount) AS "amount", '
      + 'ROUND(SUM(e.amount) * 100 / NULLIF(SUM(SUM(e.amount)) OVER (PARTITION BY p.project_id), 0), 2) AS "ratio" '
      + 'FROM expense_resolution e '
      + 'JOIN project p ON p.project_id = e.project_id '
      + 'JOIN budget_item b ON b.budget_item_id = e.budget_item_id '
      + 'WHERE e.resolution_date BETWEEN CAST(:dateFrom AS date) AND CAST(:dateTo AS date)'
      + extraWhere(f, 'e.project_id', 'e.budget_item_id', 'e.approval_status')
      + ' GROUP BY p.project_id, p.project_name, b.budget_item_id, b.item_name, e.approval_status';
  }
  // 예산: 본예산 대비 집행(결의서 지출). 구성비는 프로젝트 예산 합계 대비 예산과목별 금액 비율.
  let sql = 'SELECT p.project_id AS "projectId", p.project_name AS "projectName", '
    + 'b.budget_item_id AS "budgetItemId", b.item_name AS "budgetItemName", '
    + 'm.fiscal_year AS "fiscalYear", m.accounting_unit AS "accountingUnit", m.status AS "budgetStatus", '
    + 'm.request_amount AS "amount", '
    + 'ROUND(m.request_amount * 100 / NULLIF(SUM(m.request_amount) OVER (PARTITION BY m.project_id), 0), 2) AS "ratio", '
    + 'COALESCE((SELECT SUM(e.amount) FROM expense_resolution e '
    + 'WHERE e.project_id = m.project_id AND e.budget_item_id = m.budget_item_id AND e.resolution_type = \'지출\' '
    + 'AND e.resolution_date BETWEEN CAST(:dateFrom AS date) AND CAST(:dateTo AS date)'
    + (f.approvalStatus !== '' ? ' AND e.approval_status = :approvalStatus' : '')
    + '), 0) AS "executedAmount", '
    + 'm.request_amount - COALESCE((SELECT SUM(e.amount) FROM expense_resolution e '
    + 'WHERE e.project_id = m.project_id AND e.budget_item_id = m.budget_item_id AND e.resolution_type = \'지출\' '
    + 'AND e.resolution_date BETWEEN CAST(:dateFrom AS date) AND CAST(:dateTo AS date)'
    + (f.approvalStatus !== '' ? ' AND e.approval_status = :approvalStatus' : '')
    + '), 0) AS "balance"';
  if (form === '상세') {
    sql += ', COALESCE((SELECT SUM(c.amount) FROM commitment c '
      + 'WHERE c.budget_item_id = m.budget_item_id AND c.purchase_request_id IN '
      + '(SELECT r.purchase_request_id FROM purchase_request r WHERE r.project_id = m.project_id)), 0) AS "committedAmount"'
      + ', COALESCE((SELECT SUM(a.amount) FROM budget_adjustment a '
      + 'WHERE a.project_id = m.project_id AND a.budget_item_id = m.budget_item_id AND a.status = \'승인\'), 0) AS "adjustedAmount"';
  }
  sql += ' FROM main_budget m '
    + 'JOIN project p ON p.project_id = m.project_id '
    + 'JOIN budget_item b ON b.budget_item_id = m.budget_item_id '
    + 'WHERE m.request_date BETWEEN CAST(:dateFrom AS date) AND CAST(:dateTo AS date)'
    + extraWhere(f, 'm.project_id', 'm.budget_item_id', 'TRUE');
  return sql.replace(' AND TRUE', '');
}

@Controller('api/v1')
export class FnSfr00502Controller {
  @Get('/budget-execution-status')
  async listBudgetExecutionStatus(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자', '임직원');
    const q = checks.queryOf(req.query);
    const statusItem = text(q['statusItem']);
    const dateFrom = text(q['dateFrom']);
    const dateTo = text(q['dateTo']);
    const missing: string[] = [];
    if (statusItem === '') {
      missing.push('조회 항목');
    }
    if (dateFrom === '') {
      missing.push('조회 기간 시작');
    }
    if (dateTo === '') {
      missing.push('조회 기간 종료');
    }
    if (missing.length > 0) {
      throw new ApiError(422, 'STATUS_CONDITION_MISSING', '필수 조회 조건이 누락되었습니다: ' + missing.join(', '));
    }
    if (!STATUS_ITEMS.includes(statusItem)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 항목 값이 올바르지 않습니다.');
    }
    if (!DATE_PATTERN.test(dateFrom) || !DATE_PATTERN.test(dateTo)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 기간은 YYYY-MM-DD 형식이어야 합니다.');
    }
    if (dateFrom > dateTo) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 기간 시작일이 종료일보다 늦을 수 없습니다.');
    }
    const form = text(q['comparisonForm']) || '기본';
    if (!COMPARISON_FORMS.includes(form)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '예실 대비 구분이 올바르지 않습니다.');
    }
    const approvalStatus = text(q['approvalStatus']);
    if (approvalStatus !== '' && !APPROVAL_STATUSES.includes(approvalStatus)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '결재 상태 값이 올바르지 않습니다.');
    }
    const filter: Filter = {
      projectId: idText(q['projectId'], '프로젝트'),
      budgetItemId: idText(q['budgetItemId'], '예산과목'),
      approvalStatus,
    };
    const page = wholeNumber(q['page'], 'page', 0);
    const size = Math.min(wholeNumber(q['size'], 'size', DEFAULT_SIZE), MAX_SIZE);
    if (size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', 'size 값이 올바르지 않습니다.');
    }
    const params: Record<string, unknown> = { dateFrom, dateTo };
    if (filter.projectId !== '') {
      params.projectId = filter.projectId;
    }
    if (filter.budgetItemId !== '') {
      params.budgetItemId = filter.budgetItemId;
    }
    if (approvalStatus !== '') {
      params.approvalStatus = approvalStatus;
    }
    const base = baseSql(statusItem, form, filter);
    return transaction(async (db) => {
      const counted = await db.query('SELECT COUNT(*) AS "total" FROM (' + base + ') t', params);
      const total = Number(counted[0]['total']);
      const rows = await db.query(
        'SELECT * FROM (' + base + ') t ORDER BY "projectId", "budgetItemId" LIMIT :limit OFFSET :offset',
        { ...params, limit: size, offset: page * size },
      );
      return { items: [{ rows }], page, size, total };
    });
  }
}

