import { useState } from 'react';
import { call, useData, Badge, Num, Filters, Band, DataTable, Pager, Drawer, Pairs, Tiles, Field, Select, DateInput, LookupSelect, RefName, ErrorText } from '../kit';
import type { PageProps, Row, Page, Column } from '../kit';

const SIZE = 20;
const STATUS_ITEMS: [string, string][] = [['품의서', '품의서'], ['원인행위', '원인행위'], ['결의서', '결의서'], ['예산', '예산']];
const FORMS: [string, string][] = [['기본', '기본'], ['상세', '상세']];
const APPROVAL_STATUSES: [string, string][] = ['기안', '결재대기', '진행중', '승인', '보류', '반려', '회수', '완료'].map((s): [string, string] => [s, s]);

export default function FnSfr00502Page({ role, notify }: PageProps) {
  const [statusItem, setStatusItem] = useState('');
  const [dateFrom, setDateFrom] = useState('');
  const [dateTo, setDateTo] = useState('');
  const [projectId, setProjectId] = useState<number | string>('');
  const [budgetItemId, setBudgetItemId] = useState<number | string>('');
  const [comparisonForm, setComparisonForm] = useState('기본');
  const [approvalStatus, setApprovalStatus] = useState('');
  const [applied, setApplied] = useState<Row | null>(null);
  const [formError, setFormError] = useState('');
  const [page, setPage] = useState(0);
  const [detail, setDetail] = useState<Row | null>(null);

  const { data, error } = useData<Page<Row> | undefined>(async () => {
    if (!applied) {
      return undefined;
    }
    return call<Page<Row>>('GET', '/budget-execution-status', role, undefined, { ...applied, page, size: SIZE });
  }, [applied, page]);

  const rows: Row[] = data ? data.items.flatMap((item) => (item.rows as Row[]) ?? []) : [];
  const isBudget = applied?.statusItem === '예산';
  const totalAmount = rows.reduce((sum, r) => sum + Number(r.amount ?? 0), 0);
  const totalCount = rows.reduce((sum, r) => sum + Number(r.count ?? 1), 0);

  function search() {
    const missing: string[] = [];
    if (!statusItem) {
      missing.push('조회 항목');
    }
    if (!dateFrom) {
      missing.push('조회 기간 시작');
    }
    if (!dateTo) {
      missing.push('조회 기간 종료');
    }
    if (missing.length > 0) {
      setFormError('필수 조회 조건이 누락되었습니다: ' + missing.join(', '));
      return;
    }
    setFormError('');
    setPage(0);
    setApplied({ statusItem, dateFrom, dateTo, projectId, budgetItemId, comparisonForm, approvalStatus });
  }

  function reset() {
    setStatusItem('');
    setDateFrom('');
    setDateTo('');
    setProjectId('');
    setBudgetItemId('');
    setComparisonForm('기본');
    setApprovalStatus('');
    setApplied(null);
    setFormError('');
    setPage(0);
  }

  const columns: Column<Row>[] = [
    { key: 'projectId', label: '프로젝트', render: (r) => <RefName table="project" role={role} value={r.projectId} /> },
    { key: 'budgetItemId', label: '예산과목', render: (r) => <RefName table="budget_item" role={role} value={r.budgetItemId} /> },
  ];
  if (isBudget) {
    columns.push(
      { key: 'fiscalYear', label: '기수' },
      { key: 'amount', label: '예산 금액', render: (r) => <Num value={r.amount} /> },
      { key: 'executedAmount', label: '집행 금액', render: (r) => <Num value={r.executedAmount} /> },
      { key: 'balance', label: '잔액', render: (r) => <Num value={r.balance} /> },
    );
    if (applied?.comparisonForm === '상세') {
      columns.push(
        { key: 'committedAmount', label: '원인행위 금액', render: (r) => <Num value={r.committedAmount} /> },
        { key: 'adjustedAmount', label: '추가 조정 금액', render: (r) => <Num value={r.adjustedAmount} /> },
      );
    }
  } else {
    columns.push(
      { key: 'approvalStatus', label: '결재 상태', render: (r) => <Badge value={r.approvalStatus} /> },
      { key: 'count', label: '건수', render: (r) => <Num value={r.count} /> },
      { key: 'amount', label: '금액', render: (r) => <Num value={r.amount} /> },
    );
  }
  columns.push({ key: 'ratio', label: '구성비', render: (r) => (r.ratio === null || r.ratio === undefined ? '-' : String(r.ratio) + '%') });

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>조회 현황</h2>
        <Tiles items={[
          ['조회 건수', <Num value={data ? data.total : 0} />],
          ['표시 건수 합계', <Num value={totalCount} />],
          ['표시 금액 합계', <Num value={totalAmount} />],
        ]} />
      </section>
      <section className="box span-12">
        <h2>예산 집행 현황</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="조회 항목" required>
            <Select value={statusItem} onChange={setStatusItem} options={STATUS_ITEMS} />
          </Field>
          <Field label="조회 기간 시작" required>
            <DateInput value={dateFrom} onChange={setDateFrom} />
          </Field>
          <Field label="조회 기간 종료" required>
            <DateInput value={dateTo} onChange={setDateTo} />
          </Field>
          <Field label="프로젝트">
            <LookupSelect table="project" role={role} value={projectId} onChange={setProjectId} />
          </Field>
          <Field label="예산과목">
            <LookupSelect table="budget_item" role={role} value={budgetItemId} onChange={setBudgetItemId} />
          </Field>
          <Field label="예실 대비 기본 또는 상세">
            <Select value={comparisonForm} onChange={setComparisonForm} options={FORMS} />
          </Field>
          <Field label="결재 상태">
            <Select value={approvalStatus} onChange={setApprovalStatus} options={APPROVAL_STATUSES} placeholder="전체" />
          </Field>
        </Filters>
        {formError ? <ErrorText text={formError} /> : null}
        {error ? <ErrorText text={error} /> : null}
        <Band total={data?.total} />
        <DataTable
          columns={columns}
          rows={rows}
          onRowClick={(r) => setDetail(r)}
          empty={applied ? '조회 결과가 없습니다.' : '조회 조건을 선택하고 조회를 눌러 주세요.'}
        />
        <Pager page={page} size={SIZE} total={data?.total ?? 0} onPage={setPage} />
      </section>
      {detail ? (
        <Drawer title="집행 현황 상세" onClose={() => setDetail(null)}>
          <Pairs items={[
            ['프로젝트', <RefName table="project" role={role} value={detail.projectId} />],
            ['예산과목', <RefName table="budget_item" role={role} value={detail.budgetItemId} />],
            ['결재 상태', detail.approvalStatus ? <Badge value={detail.approvalStatus} /> : '-'],
            ['건수', <Num value={detail.count} />],
            ['금액', <Num value={detail.amount} />],
            ['집행 금액', <Num value={detail.executedAmount} />],
            ['잔액', <Num value={detail.balance} />],
            ['구성비', detail.ratio === null || detail.ratio === undefined ? '-' : String(detail.ratio) + '%'],
          ]} />
        </Drawer>
      ) : null}
    </div>
  );
}
